function openAI(){ aiPanel.classList.add('open'); if(aiFab) aiFab.classList.add('is-hidden'); if(!aiStarted){aiStarted=true;greet();} saveTevi(); setTimeout(()=>aiInput.focus(),350); }
function closeAI(){ aiPanel.classList.remove('open'); if(aiFab) aiFab.classList.remove('is-hidden'); saveTevi(); var nb=document.querySelector('.nav-ai'); if(nb) nb.focus(); }
if(aiFab) aiFab.addEventListener('click', openAI);
aiClose.addEventListener('click', closeAI);
document.addEventListener('keydown', e => { if (e.key === 'Escape' && aiPanel.classList.contains('open')) closeAI(); });
document.querySelectorAll('.ai-open-link').forEach(b => b.addEventListener('click', openAI));
function addMsg(html, who, skipLog){ const m=document.createElement('div'); m.className='msg '+who; m.innerHTML=html; aiBody.appendChild(m); aiBody.scrollTop=aiBody.scrollHeight; if(!skipLog){ teviLog.push({t:'msg',who:who,html:html}); saveTevi(); } return m; }
function addChips(items, skipLog){ const c=document.createElement('div'); c.className='chips'; items.forEach(t=>{const b=document.createElement('button');b.className='chip';b.textContent=t;b.addEventListener('click',()=>ask(t));c.appendChild(b);}); aiBody.appendChild(c); aiBody.scrollTop=aiBody.scrollHeight; if(!skipLog){ teviLog.push({t:'chips',items:items}); saveTevi(); } }
function typing(){ const t=document.createElement('div'); t.className='typing'; t.innerHTML='<i></i><i></i><i></i>'; aiBody.appendChild(t); aiBody.scrollTop=aiBody.scrollHeight; return t; }
function greet(){
  var L = TEVI[tlang()];
  addMsg(L.greet, 'bot');
  addChips(L.chips);
}
// Si se cambia de idioma y Tevi solo ha saludado (sin conversación real), re-saluda en el nuevo idioma.
document.addEventListener('langchange', function(){
  if(!aiStarted) return;
  var hasUser = teviLog.some(function(it){ return it.t==='msg' && it.who==='user'; });
  if(hasUser) return;
  teviLog = []; teviHistory = [];
  if(aiBody) aiBody.innerHTML = '';
  greet();
});
const escapeHtml = s => s.replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const suggest = (exclude) => KB.filter(k => k !== exclude).sort(()=>0.5-Math.random()).slice(0,3).map(k=>k.q);
var SITE_ROOT = (function(){ var s=(document.querySelector('script[src*="app.js"]')||{}).src||''; return s ? s.replace(/assets\/app\.js.*$/, '') : ''; })();
var PAGE_LABELS = {nosotros:'Nosotros', servicios:'Servicios', casos:'Casos de éxito', contacto:'Contacto'};
var SVC_LABELS = {'sap':'SAP','oracle-jd-edwards':'Oracle JD Edwards','ia-empresarial':'IA Empresarial','desarrollo-a-medida':'Desarrollo a medida','modernizacion-legacy':'Modernización legacy','assessment':'Assessment'};
var LINK_STYLE = ' style="color:var(--red);font-weight:600;text-decoration:underline"';
function formatAI(text){
  return escapeHtml(text)
    .replace(/(info@[a-z0-9.\-]+\.[a-z]{2,})/gi, '<a href="mailto:$1">$1</a>')
    // UNA sola pasada (sub-ruta de servicio primero en la alternancia) para no
    // reprocesar los <a> ya creados y evitar enlaces anidados.
    .replace(/\/servicios\/(sap|oracle-jd-edwards|ia-empresarial|desarrollo-a-medida|modernizacion-legacy|assessment)\/|\/(nosotros|servicios|casos|contacto)\//g, function(m, sub, base){
      if(sub) return '<a href="'+SITE_ROOT+'servicios/'+sub+'/"'+LINK_STYLE+'>'+SVC_LABELS[sub]+'</a>';
      return '<a href="'+SITE_ROOT+base+'/"'+LINK_STYLE+'>'+PAGE_LABELS[base]+'</a>';
    })
    .replace(/\n{2,}/g, '<br><br>').replace(/\n/g, '<br>');
}
function localAnswer(q){
  const hit = search(q);
  if (hit){ addMsg(hit.a, 'bot'); addChips(suggest(hit)); }
  else {
    var L = TEVI[tlang()];
    addMsg(L.noans, 'bot');
    addChips(L.noansChips);
  }
}
// Sugerencia de navegación: si Tevi recomienda UNA sección y no estamos ya en
// ella, muestra un botón "Ir a <sección> →". Al pulsarlo te lleva allí y, AL
// LLEGAR, hace scroll hasta el contenido concreto que pediste (p. ej. "Gabriel
// Grosso" en /nosotros/) y lo resalta. Si NO lo pulsas, el aviso desaparece solo
// a los 15 s (con la misma barra de cuenta atrás). La conversación persiste.
var _goTimer = null, lastQ = '';
function cancelAutoGo(){ if(_goTimer){ clearTimeout(_goTimer); _goTimer = null; } var n = aiBody.querySelector('.ai-go'); if(n) n.remove(); }
function termsOf(s){ return norm(s||'').split(/\s+/).filter(function(t){ return t.length>2 && !STOP.has(t); }); }
function setScrollTarget(url, terms){
  try {
    if(!terms || !terms.length) return;
    var p = new URL(url, location.href).pathname.replace(/index\.html$/,'');
    sessionStorage.setItem('tevi_scroll', JSON.stringify({ path:p, terms:terms, ts:Date.now() }));
  } catch(e){}
}
// Busca en la página el elemento que mejor coincide con los términos, lo centra
// en pantalla y lo resalta un instante. Devuelve true si lo encontró.
function scrollToTerms(terms){
  if(!terms || !terms.length) return false;
  var T = terms.map(function(t){ return norm(t); }).filter(function(t){ return t.length>2; });
  if(!T.length) return false;
  var root = document.querySelector('main') || document.body;
  var els = root.querySelectorAll('h1,h2,h3,h4,h5,p,li,td,figcaption,span,strong,b,a,div.ct,div.case-client');
  var best=null, bestScore=0;
  els.forEach(function(el){
    var txt = norm(el.textContent||'');
    if(txt.length<2 || txt.length>360) return;
    var score=0; T.forEach(function(t){ if(txt.indexOf(t)>-1) score++; });
    if(score>bestScore){ bestScore=score; best=el; }
  });
  if(best && bestScore>0){
    // Desplazamos la VENTANA con la posición medida (scrollIntoView falla por los
    // transforms de las animaciones .reveal en los ancestros). Centramos el
    // elemento dejando holgura para el nav fijo.
    var rect = best.getBoundingClientRect();
    var y = rect.top + window.pageYOffset - Math.max(96, (window.innerHeight - rect.height) / 2);
    try { window.scrollTo({ top: Math.max(0, y), behavior:'smooth' }); } catch(e){ window.scrollTo(0, Math.max(0, y)); }
    best.classList.add('ai-spot');
    setTimeout(function(){ best.classList.remove('ai-spot'); }, 2600);
    return true;
  }
  return false;
}
function offerNavigate(answer, q){
  var m = answer.match(/\/servicios\/(sap|oracle-jd-edwards|ia-empresarial|desarrollo-a-medida|modernizacion-legacy|assessment)\/|\/(nosotros|servicios|casos|contacto)\//);
  if(!m) return;
  var path = m[1] ? 'servicios/'+m[1]+'/' : m[2]+'/';
  var label = m[1] ? SVC_LABELS[m[1]] : PAGE_LABELS[m[2]];
  var url = SITE_ROOT + path, en = tlang()==='en';
  var here = location.pathname.replace(/index\.html$/,'').replace(/\/+$/,'');
  var dest;
  try { dest = new URL(url, location.href).pathname.replace(/index\.html$/,'').replace(/\/+$/,''); } catch(e){ return; }
  if(here === dest) return; // ya estamos en esa sección
  cancelAutoGo();
  var note = document.createElement('div');
  note.className = 'ai-go';
  note.innerHTML = '<button type="button" class="ai-go-btn">'+(en?'Go to ':'Ir a ')+'<b>'+label+'</b><svg class="ai-go-arrow" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h15M13 6l6 6-6 6"/></svg></button><span class="ai-go-bar" aria-hidden="true"></span>';
  aiBody.appendChild(note); aiBody.scrollTop = aiBody.scrollHeight;
  // Al pulsar el botón: navega a la sección (y enfoca el contenido al llegar).
  note.querySelector('.ai-go-btn').addEventListener('click', function(){ cancelAutoGo(); setScrollTarget(url, termsOf(q)); location.href = url; });
  // Si no se pulsa, el aviso desaparece solo a los 15 s (sin navegar).
  _goTimer = setTimeout(function(){
    _goTimer = null;
    note.classList.add('ai-go-out');
    setTimeout(function(){ if(note.parentNode) note.parentNode.removeChild(note); }, 320);
  }, 15000);
}
// Historial de la conversación: se envía al Worker para que Tevi mantenga el
// hilo (memoria de los turnos previos) y deje de sonar a robot sin contexto.
var teviHistory = [];
async function ask(q){
  lastQ = q;
  addMsg(escapeHtml(q), 'user'); aiInput.value='';
  const t = typing();
  if (AI_ENDPOINT){
    try {
      const res = await fetch(AI_ENDPOINT, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ question: q, lang: tlang(), context: await fullContext(), history: teviHistory.slice(-6) }) });
      const data = await res.json().catch(()=>({}));
      t.remove();
      if (res.ok && data.answer){
        addMsg(formatAI(data.answer), 'bot'); addChips(suggest());
        teviHistory.push({ role:'user', content:q }, { role:'assistant', content:data.answer });
        if (teviHistory.length > 16) teviHistory = teviHistory.slice(-16);
        saveTevi();
        offerNavigate(data.answer, q);
      }
      else localAnswer(q);
    } catch (e){ t.remove(); localAnswer(q); }
    return;
  }
  setTimeout(() => { t.remove(); localAnswer(q); }, 480 + Math.random()*420);
}
aiSend.addEventListener('click', () => { const v = aiInput.value.trim(); if (v) ask(v); });
// Si el usuario interactúa (escribe), cancelamos cualquier auto-navegación pendiente.
aiInput.addEventListener('keydown', () => { if(_goTimer) cancelAutoGo(); });
// Al cargar la página, restaura la conversación guardada (si la hay) para que
// Tevi sobreviva a la navegación entre páginas multipágina.
(function restoreTevi(){
  if(!aiPanel || !aiBody) return;
  var raw; try { raw = sessionStorage.getItem(TEVI_SS); } catch(e){ return; }
  if(!raw) return;
  var st; try { st = JSON.parse(raw); } catch(e){ return; }
  if(!st || !Array.isArray(st.log) || !st.log.length) return;
  teviHistory = Array.isArray(st.history) ? st.history : [];
  teviLog = st.log;
  aiStarted = true;
  replayTevi(st.log);
  if(st.open){ aiPanel.classList.add('open'); if(aiFab) aiFab.classList.add('is-hidden'); }
})();
// Si pulsas un enlace dentro de una respuesta de Tevi, guarda el objetivo de
// scroll (términos de la última pregunta) para enfocar el contenido al llegar.
if(aiBody) aiBody.addEventListener('click', function(e){
  var a = e.target.closest ? e.target.closest('a[href]') : null;
  if(!a) return;
  var href = a.getAttribute('href') || '';
  if(/^(mailto:|tel:|javascript:|#)/i.test(href)) return;
  try { if(new URL(a.href, location.href).origin === location.origin) setScrollTarget(a.href, termsOf(lastQ)); } catch(_e){}
});
// Al cargar la página, si hay un objetivo de scroll pendiente para ESTA página,
// desplaza hasta el contenido relevante y lo resalta.
(function teviScrollOnLoad(){
  var raw; try { raw = sessionStorage.getItem('tevi_scroll'); } catch(e){ return; }
  if(!raw) return;
  try { sessionStorage.removeItem('tevi_scroll'); } catch(e){}
  var t; try { t = JSON.parse(raw); } catch(e){ return; }
  if(!t || !t.path || !t.terms) return;
  if(t.ts && (Date.now() - t.ts) > 30000) return;
  var here = location.pathname.replace(/index\.html$/,'');
  if(here !== t.path) return;
  setTimeout(function(){ scrollToTerms(t.terms); }, 550);
})();

/* Carrusel de portada */
(function(){
  var car = document.getElementById('top');
  if(!car || !car.classList.contains('hero-carousel')) return;
  var slides = [].slice.call(car.querySelectorAll('.hc-slide'));
  var dots = [].slice.call(car.querySelectorAll('.hc-dot'));
  if(slides.length < 2) return;
  var reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  var i = 0, timer = null, paused = false, rt = null;
  function schedule(){
    if(timer){ clearTimeout(timer); timer = null; }
    if(reduce || paused || document.hidden) return;
    timer = setTimeout(function(){ go(i+1); }, i===0 ? 9000 : (slides[i] && slides[i].classList.contains('hc-tevi') ? 12000 : 7000));
  }
  function go(n){
    i = (n + slides.length) % slides.length;
    slides.forEach(function(s,k){ s.classList.toggle('is-active', k===i); });
    dots.forEach(function(d,k){ d.classList.toggle('on', k===i); });
    var dk=slides[i].classList.contains('hc-msg');
    var nv=document.getElementById('nav'); if(nv) nv.classList.toggle('nav-dark', dk);
    car.classList.toggle('hc-dark', dk);
    schedule();
  }
  dots.forEach(function(d,k){ d.addEventListener('click', function(){ paused=false; go(k); }); });
  car.addEventListener('pointerdown', function(){ paused = true; if(timer){ clearTimeout(timer); timer=null; } });
  car.addEventListener('pointerup', function(){ if(rt) clearTimeout(rt); rt = setTimeout(function(){ paused=false; schedule(); }, 3500); });
  car.addEventListener('focusin', function(){ paused = true; if(timer){ clearTimeout(timer); timer=null; } });
  car.addEventListener('focusout', function(){ paused = false; schedule(); });
  document.addEventListener('visibilitychange', function(){ if(document.hidden){ if(timer){clearTimeout(timer);timer=null;} } else { schedule(); } });
  schedule();
})();

